		validator.validate( command );

            entity.setDemandSignalId( command.getDemandSignalId() );
            entity.setExternalReference( command.getExternalReference() );
            entity.setRequestedDate( command.getRequestedDate() );
            entity.setQuantity( command.getQuantity() );
            entity.setDemandType( command.getDemandType() );

